CREATE COLUMN TABLE "TEST_AP"."OCDP" ("ClsDateNum" SMALLINT CS_INT NOT NULL , "ClsDtCode" NVARCHAR(30) NOT NULL , "BsLineDate" NVARCHAR(1) DEFAULT 'S', "DueMonth" NVARCHAR(1) DEFAULT 'N', "ExtraMonth" SMALLINT CS_INT, "ExtraDay" SMALLINT CS_INT, PRIMARY KEY ("ClsDateNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCDP_ABS_ENTRY" ON "TEST_AP"."OCDP" ( "ClsDtCode" ASC )